void effStarStoneDraw(CameraId cameraId, EffectEntry* effect) {
    EffStarStoneWork* w = effect->userdata;
    switch (w->type) {
    case 0:
    case 6:
        effStarStoneDisp_1(cameraId, effect);
        break;
    default:
        effStarStoneDisp_2(cameraId, effect);
        break;
    }
}

